<?php
require __DIR__ . '/backend/common.php'; require_admin(); $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { try { $id=(int) input('id'); $decision=input('decision'); if (!in_array($decision,['approved','rejected'],true)) throw new InvalidArgumentException('Invalid decision.'); $project=$conn->execute_query("SELECT user_id,title FROM projects WHERE id=? AND approval='pending'",[$id])->fetch_assoc(); if(!$project) throw new InvalidArgumentException('Project is no longer pending.'); $conn->execute_query('UPDATE projects SET approval=? WHERE id=?',[$decision,$id]); notify_user($project['user_id'],'Your project “'.$project['title'].'” was '.$decision.'.'); flash('Project '.$decision.'.'); go('admin-project-reviews.php'); } catch(Throwable $e){$error=page_error($e);} }
$projects=$conn->query("SELECT p.*,u.full_name,u.email FROM projects p JOIN users u ON u.id=p.user_id WHERE p.approval='pending' ORDER BY p.created_at")->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Project Reviews · Admin</title><link rel="stylesheet" href="portal.css"></head><body class="portal-page"><div class="app-container portal-layout"><?php require __DIR__.'/backend/sidebar.php'; ?><main class="main-content"><div class="live-content"><h1>Project reviews</h1><p>Approve research projects before they are discoverable or open for join requests.</p><?php require __DIR__.'/backend/admin_nav.php'; ?><?php if($error): ?><p class="notice error"><?= e($error) ?></p><?php endif; ?><?php if(!$projects): ?><p class="box empty">The project review queue is clear.</p><?php endif; ?><?php foreach($projects as $project): ?><article class="box"><span class="tag">Awaiting approval</span><h2><?= e($project['title']) ?></h2><p class="muted">Proposed by <?= e($project['full_name']) ?> · <?= e($project['department']) ?> · <?= e($project['status']) ?></p><p><?= nl2br(e($project['description'])) ?></p><form method="post"><input type="hidden" name="id" value="<?= (int)$project['id'] ?>"><button name="decision" value="approved">Approve project</button> <button class="danger" name="decision" value="rejected">Reject</button></form></article><?php endforeach; ?></div></main></div></body></html>
